// === Tab: texture ===
function genTexture(ptr,mode=0,inv=false,b=2,c=color(255)){
	let tex = createGraphics(w*2,w*2);
	tex.stroke(c);
	if (inv) { tex.image(ptr,0,0);  tex.erase(); }
	if (mode==0) {
		tex.strokeWeight(b);
		for (let i = 0; i < w/2; i++) { tex.line(i*4,0,i*4,w); }
	}
	if (mode==1) {
		tex.strokeWeight(b);
		for (let i = 0; i < w/2; i++) { tex.line(0,i*4,w,i*4); }
	}
	if (mode==2) {
		tex.strokeWeight(b);
		for (let i = 0; i < w/2; i++) { tex.line(0,i*4,i*4,0); }
	}
	if (mode==3) {
		tex.strokeWeight(0.5);
		for (let i = 0; i < w/2; i++) {
			for (let j = 0; j < w/2; j++) {
				tex.point(i*4,j*4);  tex.point(i*4+2,j*4+2);
			}
		}
	}
	if (mode==4) {
		tex.strokeWeight(b);  tex.noFill();
		for (let j = 0; j < w/2; j++) {
			tex.beginShape();
			for (let i = 0; i < w*2; i++) { tex.vertex(j*4+cos(i/2),i); }
			tex.endShape();
		}
	}
	if (mode==5) {
		tex.strokeWeight(b);  tex.noFill();
		for (let j = 0; j < w/2; j++) {
			tex.beginShape();
			for (let i = 0; i < w*2; i++) { tex.vertex(i,j*4+cos(i/2)); }
			tex.endShape();
		}
	}
	return tex;
}

