function drawPolygon(pg, n, px, py, d, rot=0) {
	pg.beginShape();
	for (let i = 0; i < n; i++) { pg.vertex(cos(360/n*i+rot)*(d/2)+px, sin(360/n*i+rot)*(d/2)+py); }
	pg.endShape(CLOSE);
}

function polygonPoint(t, rot, n) {
	let an = 360 / n;
	return createVector(
		cos(t+rot) * (cos(an / 2) / cos(an * (t / an - floor(t / an)) - an / 2)),
		sin(t+rot) * (cos(an / 2) / cos(an * (t / an - floor(t / an)) - an / 2))
	);
}

function shadow(pg, bShadow, col=color(30), blur=10, offset=5) {
	if (bShadow) {
		pg.drawingContext.shadowOffsetX = offset;
		pg.drawingContext.shadowOffsetY = offset;
		pg.drawingContext.shadowBlur = blur;
		pg.drawingContext.shadowColor = col;
		// pg.drawingContext.shadowColor = color(30);
		// pg.drawingContext.shadowColor = color(200);
		// pg.drawingContext.shadowColor = color(pal[1]);
		// drawingContext.shadowColor = bgColor;
	} else {
		pg.drawingContext.shadowOffsetX = 0;
		pg.drawingContext.shadowOffsetY = 0;
		pg.drawingContext.shadowBlur = 0;
	}
}

function alphaColor(c,a){
	return color(hue(window.color(c)),saturation(window.color(c)),brightness(window.color(c)),a);
}

function genEffect() {
	let pg = createGraphics(width, height);
	pg.background(255, 10);

	// glitch
	pg.strokeWeight(1);
	for (let i = 0; i < width / 4; i++) {
		pg.stroke(red(window.color(bgColor)), green(window.color(bgColor)), blue(window.color(bgColor)), random(30));
		let px = random(width);
		let py = random(height);
		pg.line(px, py, px, py + 200);
	}

	// noise
	pg.strokeWeight(1);
	for (let i = 0; i < width * height / 20; i++) {
		pg.stroke(red(window.color(bgColor)), green(window.color(bgColor)), blue(window.color(bgColor)), random(100));
		let px = random(width);
		let py = random(height);
		pg.point(px, py);
	}

	return pg;
}

